INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b69b-7385-b3c7-64e19ae59966'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'The least common multiple of 12, x and 28 is 420. Find two possible values of x between 12 and 100.', '15 and 35', '420 = 2^2 × 3 × 5 × 7. Since 12 = 2^2 × 3 and 28 = 2^2 × 7, x must contribute a factor of 5 without creating higher powers that change the LCM. Two possible values are 15 and 35.', 'Medium', '{"tags":"numbers,lcm,factors","subtopic":"lcm","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.819Z'::timestamptz, '2026-07-26T12:42:25.819Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b69e-73de-893e-74388ffc703e'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Jessica invests $4540 at a rate of r% per year compound interest. At the end of 10 years, she has earned $1328.54 in interest. Find the value of r.', '2.5%', 'Final amount = 4540 + 1328.54 = 5868.54. So 4540(1 + r/100)^10 = 5868.54. Divide by 4540 to get (1 + r/100)^10 = 1.292. Taking the 10th root gives 1 + r/100 ≈ 1.025. Therefore r = 2.5%.', 'Medium', '{"tags":"percentages,compound-interest,finance","subtopic":"compound interest","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.822Z'::timestamptz, '2026-07-26T12:42:25.822Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6af-777a-893b-e66b9f69cf0e'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'A regular polygon has interior angle to exterior angle ratio 5:4. Explain why this is impossible.', 'The number of sides is not a whole number.', 'Let the interior angle be 5x and the exterior angle be 4x. Since they add up to 180°, 9x = 180, so x = 20 and the exterior angle is 80°. The number of sides would be 360 ÷ 80 = 4.5, which is not an integer, so such a regular polygon is impossible.', 'Medium', '{"tags":"angles,polygons,reasoning","subtopic":"polygons","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.839Z'::timestamptz, '2026-07-26T12:42:25.839Z'::timestamptz) ON CONFLICT (id) DO NOTHING;